create extension if not exists vector;
create table orgs (id uuid primary key default gen_random_uuid(), name text not null, kind text not null check (kind in ('club','agency','federation','academy','internal')));
create table app_users (id uuid primary key references auth.users, org_id uuid references orgs, role text not null check (role in ('scout','agent','federation','coach','player','guardian','tagger','admin')));
create table players (id uuid primary key default gen_random_uuid(), display_name text not null, birth_year int, nationality text, preferred_foot text check (preferred_foot in ('left','right','both')), primary_position text, id_verified boolean not null default false, visible_to_scouts boolean not null default false);
create table player_identity (player_id uuid primary key references players, legal_name text not null, date_of_birth date not null, id_document_path text, verified_by text, verified_at timestamptz);
create table consents (id uuid primary key default gen_random_uuid(), player_id uuid not null references players, signed_by uuid not null references app_users, scope text[] not null, signed_at timestamptz not null default now(), revoked_at timestamptz);
create table competitions (id uuid primary key default gen_random_uuid(), name text not null, country text not null, age_group text, season text not null);
create table teams (id uuid primary key default gen_random_uuid(), name text not null, country text not null);
create table matches (id uuid primary key default gen_random_uuid(), competition_id uuid not null references competitions, home_team_id uuid not null references teams, away_team_id uuid not null references teams, kickoff_at timestamptz, mux_asset_id text, status text not null default 'uploaded' check (status in ('uploaded','tagging','review','published')));
create table lineups (match_id uuid references matches, player_id uuid references players, team_id uuid not null references teams, shirt_number int, position text, minutes_played int not null default 0, primary key (match_id, player_id));
create table events (id uuid primary key default gen_random_uuid(), match_id uuid not null references matches, player_id uuid references players, team_id uuid not null references teams, period int not null, video_seconds numeric not null, type text not null, outcome text, x numeric, y numeric, end_x numeric, end_y numeric, body_part text, extra jsonb not null default '{}', related_event_id uuid references events, tagger_id uuid references app_users);
create index on events (match_id, video_seconds);
create index on events (player_id, type);
create table physical_tests (id uuid primary key default gen_random_uuid(), player_id uuid not null references players, test text not null, value numeric not null, unit text not null, tested_at date not null, verified boolean not null default false);
create table player_season_metrics (player_id uuid references players, competition_id uuid references competitions, role text not null, minutes int not null, per90 jsonb not null, percentiles jsonb not null, style vector(16), primary key (player_id, competition_id, role));
create index on player_season_metrics using hnsw (style vector_cosine_ops);
create table shortlists (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app_users, name text not null);
create table shortlist_players (shortlist_id uuid references shortlists on delete cascade, player_id uuid references players, note text, primary key (shortlist_id, player_id));
create table profile_views (viewer_id uuid references app_users, player_id uuid references players, viewed_at timestamptz default now());
create table jobs (id bigserial primary key, kind text not null, payload jsonb not null, status text not null default 'queued', run_after timestamptz default now(), attempts int not null default 0);
alter table players enable row level security;
create policy scouts_read_visible on players for select using (visible_to_scouts and exists (select 1 from app_users u where u.id = auth.uid() and u.role in ('scout','agent','admin')));
alter table player_identity enable row level security;
